INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC3_D022_PROMO_DOCTRINE','Revised Doctrine');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC3_D022_PROMO_DOCTRINE_HELP','Eligible military deaths against foreign major military units grant 1 Lesson, up to 5. Spend 2 for +10% combat for 3 owner-turns or 3 for +10% Capital Science for 5. Each has a 10-owner-turn cooldown.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC3_D022_PROMO_COUNTER','Reflected Lesson');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC3_D022_PROMO_COUNTER_HELP','+1 Sight. After surviving hostile melee combat on defense, gains +15% strength on its next attack, expiring by the end of its next owner-turn.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC3_D022_PROMO_LINEAGE','Reflection Guard');
