INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC3_D022_ABILITY_HELP','Eligible military deaths against foreign major military units grant 1 Lesson, up to 5. Spend 2 for +10% combat for 3 owner-turns or 3 for +10% Capital Science for 5. Each has a 10-owner-turn cooldown.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC3_D022_CIV_PEDIA','In Verity, failure is studied even when it is painful to remember. Its philosophers record mistakes in glass so reforms can be compared with what came before.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC3_D022_STRATEGY','Keep three Lessons for Universities when possible. Spend on Method around important technologies or Doctrine when a counteroffensive can decide a war.');
